import type { Address } from 'abitype'
import { VirtualAddress } from 'ox/tempo'
import { call } from '../../../actions/public/call.js'
import type { Client } from '../../../clients/createClient.js'
import { zeroAddress } from '../../../constants/address.js'
import { decodeAbiParameters } from '../../../utils/abi/decodeAbiParameters.js'
import { encodeAbiParameters } from '../../../utils/abi/encodeAbiParameters.js'
import { concat } from '../../../utils/data/concat.js'
import * as Addresses from '../../Addresses.js'

/** Reads fee preferences, balances, and virtual masters without dependent RPC requests. */
export async function read(
  client: Client,
  options: {
    account?: Address | undefined
    tokens?: readonly Address[] | undefined
    targets?: readonly Address[] | undefined
  },
) {
  const { account = zeroAddress, tokens = [], targets = [] } = options
  const masterIds = [
    ...new Set(targets.map((target) => VirtualAddress.parse(target).masterId)),
  ]
  const { data } = await call(client, {
    batch: false,
    data: concat([
      bytecode,
      encodeAbiParameters(
        [
          { type: 'address' },
          { type: 'address' },
          { type: 'address[]' },
          { type: 'address' },
          { type: 'bytes4[]' },
        ],
        [
          account,
          Addresses.feeManager,
          tokens,
          Addresses.addressRegistry,
          masterIds,
        ],
      ),
    ]),
  })
  const [preferredToken, preferredBalance, balances, resolved, masters] =
    decodeAbiParameters(
      [
        { type: 'address' },
        { type: 'uint256' },
        { type: 'uint256[]' },
        { type: 'bool' },
        { type: 'address[]' },
      ],
      data ?? '0x',
    )
  return {
    preferredToken,
    preferredBalance,
    balances: tokens.map((address, index) => ({
      address,
      balance: balances[index]!,
    })),
    virtualAddresses:
      resolved && targets.length > 0
        ? (Object.fromEntries(
            targets.map((target) => {
              const master =
                masters[
                  masterIds.indexOf(VirtualAddress.parse(target).masterId)
                ]!
              return [target, master === zeroAddress ? null : master]
            }),
          ) as Record<Address, Address | null>)
        : undefined,
  }
}

